package com.slayerstreak;

public enum MilestoneInterval
{
    EVERY_10("Every 10th", 10),
    EVERY_50("Every 50th", 50),
    EVERY_100("Every 100th", 100),
    EVERY_250("Every 250th", 250);

    private final String label;
    private final int value;

    MilestoneInterval(String label, int value)
    {
        this.label = label;
        this.value = value;
    }

    @Override
    public String toString()
    {
        return label;
    }

    public int getValue()
    {
        return value;
    }
}

package com.slayerstreak;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Units;

@ConfigGroup("slayerstreak")
public interface SlayerStreakConfig extends Config
{
    @ConfigSection(
            name = "General",
            description = "Core streak and milestone settings.",
            position = 0
    )
    String generalSection = "general";

    @ConfigSection(
            name = "Misc",
            description = "Infobox and notification settings.",
            position = 1
    )
    String miscSection = "misc";

    @ConfigItem(
            keyName = "milestoneInterval",
            name = "Milestone interval",
            description = "How often you want to be reminded to go to Konar.",
            section = generalSection,
            position = 0
    )
    default MilestoneInterval milestoneInterval()
    {
        return MilestoneInterval.EVERY_50;
    }

    @ConfigItem(
            keyName = "hideNonKonarAtMilestone",
            name = "Hide non-Konar at milestone",
            description = "Hides non-Konar Slayer masters at chosen milestone interval.",
            section = generalSection,
            position = 1
    )
    default boolean hideNonKonarAtMilestone()
    {
        return true;
    }

    @ConfigItem(
            keyName = "hideNonKonarNpcContact",
            name = "Hide non-Konar (NPC Contact)",
            description = "Hides non-Konar Slayer masters in NPC Contact menu at chosen milestone interval.",
            section = generalSection,
            position = 2
    )
    default boolean hideNonKonarNpcContact()
    {
        return true;
    }

    @ConfigItem(
            keyName = "highlightNonKonarAtMilestone",
            name = "Highlight non-Konar on milestone",
            description = "Outlines non-Konar Slayer masters in red at chosen milestone interval.",
            section = generalSection,
            position = 3
    )
    default boolean highlightNonKonarAtMilestone()
    {
        return false;
    }

    @ConfigItem(
            keyName = "wildySlayerStreak",
            name = "Wilderness Slayer streak",
            description = "Show your wilderness slayer streak instead of your normal one (Milestone interval and restricting slayer masters options will not work with this on).",
            section = generalSection,
            position = 3
    )
    default boolean wildySlayerStreak()
    {
        return false;
    }

    @ConfigItem(
            keyName = "infoboxTimeout",
            name = "Infobox timeout",
            description = "How long until the infobox disappears when doing non-Slayer activities. Input 0 for it to never disappear.",
            section = miscSection,
            position = 0
    )
    @Units(Units.MINUTES)
    default int infoboxTimeout()
    {
        return 10;
    }

    @ConfigItem(
            keyName = "desktopNotification",
            name = "Desktop notification",
            description = "Sends a desktop notification when your next task will be a milestone, so you don't miss it even if the game window isn't focused.",
            section = miscSection,
            position = 1
    )
    default boolean desktopNotification()
    {
        return true;
    }
}

package com.slayerstreak;

import java.awt.Color;
import java.awt.image.BufferedImage;
import net.runelite.client.ui.overlay.infobox.InfoBox;

class SlayerStreakInfoBox extends InfoBox
{
    private final SlayerStreakPlugin plugin;

    SlayerStreakInfoBox(BufferedImage image, SlayerStreakPlugin plugin)
    {
        super(image, plugin);
        this.plugin = plugin;
    }

    @Override
    public String getText()
    {
        return String.valueOf(plugin.isWildernessMode() ? plugin.getWildyStreak() : plugin.getStreak());
    }

    @Override
    public Color getTextColor()
    {
        if (plugin.isWildernessMode())
        {
            return Color.GREEN;
        }

        return plugin.isOneTaskFromMilestone() ? Color.RED : Color.GREEN;
    }

    private static final String LABEL = "<col=ffff00>";
    private static final String VALUE = "<col=ffffff>";

    @Override
    public String getTooltip()
    {
        if (plugin.isWildernessMode())
        {
            return LABEL + "Wilderness Streak: " + VALUE + plugin.getWildyStreak()
                    + "</br>" + LABEL + "Points: " + VALUE + plugin.getPoints();
        }

        return LABEL + "Streak: " + VALUE + plugin.getStreak()
                + "</br>" + LABEL + "Next milestone: " + VALUE + plugin.getNextMilestone() + " (" + plugin.getTasksUntilNextMilestone() + ")"
                + "</br>" + LABEL + "Points: " + VALUE + plugin.getPoints();
    }
}

package com.slayerstreak;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;

import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.outline.ModelOutlineRenderer;

class SlayerStreakOverlay extends Overlay
{
    private static final String KRYSTILIA_NAME = "Krystilia";
    private static final int OUTLINE_WIDTH = 2;
    private static final int OUTLINE_FEATHER = 2;

    private final Client client;
    private final SlayerStreakPlugin plugin;
    private final SlayerStreakConfig config;
    private final ModelOutlineRenderer modelOutlineRenderer;

    @Inject
    private SlayerStreakOverlay(Client client, SlayerStreakPlugin plugin, SlayerStreakConfig config, ModelOutlineRenderer modelOutlineRenderer)
    {
        this.client = client;
        this.plugin = plugin;
        this.config = config;
        this.modelOutlineRenderer = modelOutlineRenderer;
        setLayer(OverlayLayer.ABOVE_SCENE);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (config.wildySlayerStreak())
        {
            for (NPC npc : client.getTopLevelWorldView().npcs())
            {
                if (KRYSTILIA_NAME.equals(npc.getName()))
                {
                    modelOutlineRenderer.drawOutline(npc, OUTLINE_WIDTH, Color.BLACK, OUTLINE_FEATHER);
                }
            }

            return null;
        }

        if (!config.highlightNonKonarAtMilestone() || !plugin.isOneTaskFromMilestone())
        {
            return null;
        }

        for (NPC npc : client.getTopLevelWorldView().npcs())
        {
            String name = npc.getName();
            if (name != null && SlayerStreakPlugin.RESTRICTED_SLAYER_MASTERS.contains(name))
            {
                modelOutlineRenderer.drawOutline(npc, OUTLINE_WIDTH, Color.RED, OUTLINE_FEATHER);
            }
        }

        return null;
    }
}

package com.slayerstreak;

import java.util.Arrays;
import net.runelite.api.MenuEntry;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.client.util.Text;
import java.awt.Color;
import java.awt.image.BufferedImage;
import java.time.Duration;
import java.time.Instant;
import java.util.Set;
import javax.inject.Inject;

import com.google.inject.Provides;

import java.util.regex.Pattern;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.NPC;
import net.runelite.api.Renderable;
import net.runelite.api.Skill;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.StatChanged;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.Notifier;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.callback.Hooks;
import net.runelite.client.chat.ChatMessageBuilder;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.ui.overlay.infobox.InfoBoxManager;

@PluginDescriptor(
        name = "Slayer Streak",
        description = "Displays your Slayer task streak and can restrict Slayer Master interactions near milestones to prevent accidental streak loss",
        tags = {"slayer", "streak", "combat", "infobox", "task", "milestone", "wilderness"}
)
public class SlayerStreakPlugin extends Plugin
{
    // -- NPC Contact interface --
    private static final int NPC_CONTACT_GROUP_ID = 75;
    private static final int NPC_CONTACT_SCROLL_LAYER_CHILD = 4;
    private static final int[] SLAYER_MASTER_CHILD_IDS = { 5, 6, 7, 8, 9, 10, 11, 12 }; // array positions in 75.4 dynamic children; Konar (13) excluded

    // -- In-person slayer masters (includes alternate forms each master can appear as) --
    static final Set<String> RESTRICTED_SLAYER_MASTERS = Set.of(
            "Turael", "Aya",
            "Spria",
            "Mazchna", "Achtryn",
            "Vannaka",
            "Chaeldar",
            "Nieve", "Steve",
            "Duradel", "Kuradal",
            "Krystilia"
    );

    private static final String MILESTONE_REMINDER_TEXT = "Make sure to visit Konar for your next task!";
    private static final String STREAK_RESET_TEXT = "Your Slayer task streak has been reset to 0.";
    private static final Duration RESET_MESSAGE_COOLDOWN = Duration.ofHours(24);

    // -- Task-check chat detection (patterns from RuneLite's core Slayer plugin) --
    private static final Pattern TASK_CHECK_PATTERN = Pattern.compile("^(?:You're assigned to kill|You have received a new Slayer assignment from .*:) (?:[Tt]he )?(?<name>.+?)(?: (?:in|on|south of) (?:the )?(?<location>[^;]+))?(?:; only | \\()(?<amount>\\d+)(?: more to go\\.|\\))$");
    private static final String TASK_CHECK_COMPLETE_MESSAGE = "You need something new to hunt.";

    @Inject
    private Client client;

    @Inject
    private ClientThread clientThread;

    @Inject
    private Hooks hooks;

    @Inject
    private InfoBoxManager infoBoxManager;

    @Inject
    private ItemManager itemManager;

    @Inject
    private OverlayManager overlayManager;

    @Inject
    private SlayerStreakOverlay overlay;

    @Inject
    private ChatMessageManager chatMessageManager;

    @Inject
    private Notifier notifier;

    @Inject
    private SlayerStreakConfig config;

    private final Hooks.RenderableDrawListener drawListener = this::shouldDraw;

    private SlayerStreakInfoBox infoBox;
    private int streak = 0;
    private int wildyStreak = 0;
    private int points = 0;
    private int cachedXp = -1;

    private boolean infoboxVisible = false;
    private Instant lastActivity;
    private Instant lastResetMessage;

    @Provides
    SlayerStreakConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(SlayerStreakConfig.class);
    }

    @Override
    protected void startUp()
    {
        clientThread.invoke(() ->
        {
            streak = client.getVarbitValue(VarbitID.SLAYER_TASKS_COMPLETED);
            wildyStreak = client.getVarbitValue(VarbitID.SLAYER_WILDERNESS_TASKS_COMPLETED);
            points = client.getVarbitValue(VarbitID.SLAYER_POINTS);

            if (client.getGameState() == GameState.LOGGED_IN)
            {
                cachedXp = client.getSkillExperience(Skill.SLAYER);
            }
        });

        BufferedImage cape = itemManager.getImage(9787); // Slayer cape (t)
        infoBox = new SlayerStreakInfoBox(cape, this);
        overlayManager.add(overlay);
        hooks.registerRenderableDrawListener(drawListener);
    }

    @Override
    protected void shutDown()
    {
        infoBoxManager.removeInfoBox(infoBox);
        infoBox = null;
        infoboxVisible = false;
        overlayManager.remove(overlay);
        hooks.unregisterRenderableDrawListener(drawListener);
        cachedXp = -1;
    }

    @Subscribe
    public void onMenuEntryAdded(MenuEntryAdded event)
    {
        if (!shouldHideNpcContact())
        {
            return;
        }

        if (!"Astral Contact".equals(Text.removeTags(event.getTarget())))
        {
            return;
        }

        if (!RESTRICTED_SLAYER_MASTERS.contains(event.getOption()))
        {
            return;
        }

        MenuEntry[] entries = client.getMenuEntries();
        client.setMenuEntries(Arrays.copyOf(entries, entries.length - 1));
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        switch (event.getGameState())
        {
            case HOPPING:
            case LOGGING_IN:
                cachedXp = -1;
                break;
            case LOGGED_IN:
                streak = client.getVarbitValue(VarbitID.SLAYER_TASKS_COMPLETED);
                wildyStreak = client.getVarbitValue(VarbitID.SLAYER_WILDERNESS_TASKS_COMPLETED);
                points = client.getVarbitValue(VarbitID.SLAYER_POINTS);
                break;
            default:
                break;
        }
    }

    @Subscribe
    public void onVarbitChanged(VarbitChanged event)
    {
        int varbitId = event.getVarbitId();

        if (varbitId == VarbitID.SLAYER_TASKS_COMPLETED)
        {
            int newStreak = client.getVarbitValue(VarbitID.SLAYER_TASKS_COMPLETED);

            // Only react to genuine mid-session changes, not the login sync (guarded by cachedXp).
            if (cachedXp != -1)
            {
                if (streak > 0 && newStreak == 0)
                {
                    announceStreakReset();
                }

                streak = newStreak;
                registerActivity();

                if (!config.wildySlayerStreak() && isOneTaskFromMilestone())
                {
                    sendMilestoneReminder();
                }
            }
            else
            {
                streak = newStreak;
            }
        }
        else if (varbitId == VarbitID.SLAYER_WILDERNESS_TASKS_COMPLETED)
        {
            wildyStreak = client.getVarbitValue(VarbitID.SLAYER_WILDERNESS_TASKS_COMPLETED);

            if (cachedXp != -1)
            {
                registerActivity();
            }
        }
        else if (varbitId == VarbitID.SLAYER_POINTS)
        {
            points = client.getVarbitValue(VarbitID.SLAYER_POINTS);

            if (cachedXp != -1)
            {
                registerActivity();
            }
        }
    }

    @Subscribe
    public void onStatChanged(StatChanged event)
    {
        if (event.getSkill() != Skill.SLAYER)
        {
            return;
        }

        int slayerExp = event.getXp();

        if (slayerExp <= cachedXp)
        {
            return;
        }

        if (cachedXp == -1)
        {
            // this is the initial xp sent on login
            cachedXp = slayerExp;
            return;
        }

        cachedXp = slayerExp;
        registerActivity();
    }

    @Subscribe
    public void onGameTick(GameTick tick)
    {
        int timeout = config.infoboxTimeout();

        if (!infoboxVisible || timeout == 0 || lastActivity == null)
        {
            return;
        }

        if (Duration.between(lastActivity, Instant.now()).compareTo(Duration.ofMinutes(timeout)) >= 0)
        {
            infoBoxManager.removeInfoBox(infoBox);
            infoboxVisible = false;
        }
    }

    @Subscribe
    public void onChatMessage(ChatMessage event)
    {
        if (event.getType() != ChatMessageType.GAMEMESSAGE && event.getType() != ChatMessageType.SPAM)
        {
            return;
        }

        String message = Text.removeTags(event.getMessage());

        if (message.equals(TASK_CHECK_COMPLETE_MESSAGE) || TASK_CHECK_PATTERN.matcher(message).find())
        {
            registerActivity();
        }
    }

    @Subscribe
    public void onWidgetLoaded(WidgetLoaded event)
    {
        if (event.getGroupId() != NPC_CONTACT_GROUP_ID)
        {
            return;
        }

        boolean hide = shouldHideNpcContact();

        clientThread.invokeLater(() ->
        {
            Widget scrollLayer = client.getWidget(NPC_CONTACT_GROUP_ID, NPC_CONTACT_SCROLL_LAYER_CHILD);
            if (scrollLayer == null)
            {
                return;
            }

            Widget[] children = scrollLayer.getDynamicChildren();
            if (children == null)
            {
                return;
            }

            for (int index : SLAYER_MASTER_CHILD_IDS)
            {
                if (index < children.length && children[index] != null)
                {
                    children[index].setHidden(hide);
                }
            }
        });
    }

    boolean shouldDraw(Renderable renderable, boolean drawingUI)
    {
        if (renderable instanceof NPC)
        {
            NPC npc = (NPC) renderable;
            String name = npc.getName();

            if (name != null && RESTRICTED_SLAYER_MASTERS.contains(name) && shouldHideInPerson())
            {
                return false;
            }
        }

        return true;
    }

    private void registerActivity()
    {
        lastActivity = Instant.now();

        if (!infoboxVisible && infoBox != null)
        {
            infoBoxManager.addInfoBox(infoBox);
            infoboxVisible = true;
        }
    }

    private void sendMilestoneReminder()
    {
        String message = new ChatMessageBuilder()
                .append(Color.MAGENTA, MILESTONE_REMINDER_TEXT)
                .build();

        chatMessageManager.queue(QueuedMessage.builder()
                .type(ChatMessageType.CONSOLE)
                .runeLiteFormattedMessage(message)
                .build());

        if (config.desktopNotification())
        {
            notifier.notify(MILESTONE_REMINDER_TEXT);
        }
    }

    private void announceStreakReset()
    {
        Instant now = Instant.now();

        if (lastResetMessage != null && Duration.between(lastResetMessage, now).compareTo(RESET_MESSAGE_COOLDOWN) < 0)
        {
            return;
        }

        lastResetMessage = now;

        String message = new ChatMessageBuilder()
                .append(Color.RED, STREAK_RESET_TEXT)
                .build();

        chatMessageManager.queue(QueuedMessage.builder()
                .type(ChatMessageType.CONSOLE)
                .runeLiteFormattedMessage(message)
                .build());
    }

    private boolean shouldHideInPerson()
    {
        return !config.wildySlayerStreak() && config.hideNonKonarAtMilestone() && isOneTaskFromMilestone();
    }

    private boolean shouldHideNpcContact()
    {
        return !config.wildySlayerStreak() && config.hideNonKonarNpcContact() && isOneTaskFromMilestone();
    }

    boolean isOneTaskFromMilestone()
    {
        int interval = config.milestoneInterval().getValue();
        return (streak + 1) % interval == 0;
    }

    boolean isWildernessMode()
    {
        return config.wildySlayerStreak();
    }

    int getStreak()
    {
        return streak;
    }

    int getWildyStreak()
    {
        return wildyStreak;
    }

    int getPoints()
    {
        return points;
    }

    int getNextMilestone()
    {
        int interval = config.milestoneInterval().getValue();
        return ((streak / interval) + 1) * interval;
    }

    int getTasksUntilNextMilestone()
    {
        return getNextMilestone() - streak;
    }
}

